    async def roll_secret(
        self,
        application: str,
        endpoint_id: str,
        *,
        previous_secret_expires_in: typing.Optional[int] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> HookEndpointWithSecret:
        """
        Replaces the signing secret, returned here. Until `previous_secret_expires_at`, requests carry a signature with each secret, so the receiver can switch without rejecting any. Not idempotent.

        Parameters
        ----------
        application : str
            The application's `id` (`happ_…`) or your `uid` for it.

        endpoint_id : str
            The endpoint's id.

        previous_secret_expires_in : typing.Optional[int]
            Seconds the current secret keeps signing next to the new one. Default 86400 (a day), at most 604800 (a week); `0` stops it immediately.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        HookEndpointWithSecret
            The endpoint and its new secret.

        Examples
        --------
        import asyncio

        from coss import AsyncCoss

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.hooks.endpoints.roll_secret(
                application="customer_8812",
                endpoint_id="hep_01k7c8m4q2f3e9v6t5r1n0p8yz",
                previous_secret_expires_in=3600,
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.roll_secret(
            application,
            endpoint_id,
            previous_secret_expires_in=previous_secret_expires_in,
            request_options=request_options,
        )
        return _response.data

